// CSV Data Lab - descriptive statistics only. No fabricated values.
function parseCsv(text) {
  const lines = String(text).replace(/\r\n/g, '\n').split('\n').filter(function (l) { return l.length > 0; });
  const rows = lines.map(function (line) {
    const out = [];
    let cur = '';
    let inQ = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') { inQ = !inQ; continue; }
      if (ch === ',' && !inQ) { out.push(cur); cur = ''; continue; }
      cur += ch;
    }
    out.push(cur);
    return out.map(function (c) { return c.trim(); });
  });
  return rows;
}

let raw = query;
if (raw && typeof raw === 'object') {
  raw = raw.csv_data || raw.csv || raw.text || raw.query || '';
}
if (!raw || String(raw).trim().length === 0) {
  return JSON.stringify({ status: 'error', error: 'no_csv', message: 'No CSV text was provided to analyze.' });
}

const grid = parseCsv(raw);
if (grid.length < 2) {
  return JSON.stringify({ status: 'error', error: 'insufficient_data', message: 'CSV needs a header row and at least one data row.' });
}

const header = grid[0];
const dataRows = grid.slice(1);
const columns = header.length;
const rowsCount = dataRows.length;

let missing = 0;
const seen = {};
let duplicates = 0;
for (let r = 0; r < dataRows.length; r++) {
  const rowKey = dataRows[r].join('\u0001');
  if (seen[rowKey]) { duplicates++; } else { seen[rowKey] = true; }
  for (let c = 0; c < columns; c++) {
    const v = dataRows[r][c];
    if (v === undefined || v === '' || v === null) { missing++; }
  }
}

const numericCols = [];
const categoricalCols = [];
const stats = {};
const uniqueCounts = {};

for (let c = 0; c < columns; c++) {
  const name = header[c] || ('col_' + c);
  const values = [];
  const nonEmpty = [];
  let numericCount = 0;
  const uniq = {};
  for (let r = 0; r < dataRows.length; r++) {
    const v = dataRows[r][c];
    if (v === undefined || v === '') continue;
    nonEmpty.push(v);
    uniq[v] = true;
    const num = Number(v);
    if (v !== '' && !isNaN(num)) { values.push(num); numericCount++; }
  }
  uniqueCounts[name] = Object.keys(uniq).length;
  const isNumeric = nonEmpty.length > 0 && numericCount === nonEmpty.length;
  if (isNumeric) {
    numericCols.push(name);
    values.sort(function (a, b) { return a - b; });
    const n = values.length;
    const sum = values.reduce(function (a, b) { return a + b; }, 0);
    const mean = n > 0 ? sum / n : null;
    let median = null;
    if (n > 0) {
      const mid = Math.floor(n / 2);
      median = n % 2 === 0 ? (values[mid - 1] + values[mid]) / 2 : values[mid];
    }
    let std = null;
    if (n > 1 && mean !== null) {
      const variance = values.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / (n - 1);
      std = Math.sqrt(variance);
    }
    stats[name] = {
      min: n > 0 ? values[0] : null,
      max: n > 0 ? values[n - 1] : null,
      mean: mean,
      median: median,
      std: std,
    };
  } else {
    categoricalCols.push(name);
  }
}

const totalCells = rowsCount * columns;
const completeness = totalCells > 0 ? Number((((totalCells - missing) / totalCells) * 100).toFixed(2)) : 0;

const warnings = [];
if (duplicates > 0) warnings.push(duplicates + ' duplicate row(s) detected.');
if (missing > 0) warnings.push(missing + ' missing cell value(s) detected.');
if (numericCols.length === 0) warnings.push('No fully-numeric columns detected.');

const result = {
  status: 'success',
  rows: rowsCount,
  columns: columns,
  column_names: header,
  missing_values: missing,
  duplicates: duplicates,
  unique_values: uniqueCounts,
  numeric_columns: numericCols,
  categorical_columns: categoricalCols,
  statistics: stats,
  data_completeness_percent: completeness,
  warnings: warnings,
};

return JSON.stringify(result);
